from pathlib import Path
from PIL import Image,ImageOps,ImageDraw
import json,hashlib,html
root=Path(__file__).resolve().parents[1];out=root/'revisions/v18';v=out/'verification'
def registry(p):return json.loads(p.read_text(encoding='utf8').split('window.KonohaScenes=')[1].strip().rstrip(';'))
before=registry(out/'before/prototype/scenes.js');after=registry(root/'prototype/scenes.js');parts=[]
for id in ['minato','night','ramen']:
 b=next(s for s in after if s['id']==id);a=next((s for s in before if s['id']==id),None)
 pair=[('v17',a),('v18',b)] if a else [('Нова сцена',b)]
 parts.append('<section><h2>'+html.escape(b['name'])+'</h2><div class="pair '+('single' if not a else '')+'">'+''.join('<figure><figcaption>'+label+'</figcaption><a href="../../../assets/runtime/'+s['image']+'"><img src="../../../assets/runtime/'+s['image']+'" alt="'+html.escape(s['name']+' '+label)+'"></a></figure>' for label,s in pair)+'</div><details><summary>У лаунчері: TV / компактний / вузький екран</summary><div class="screens">'+''.join('<a href="'+id+'-'+str(w)+'.png"><img src="'+id+'-'+str(w)+'.png" alt="'+html.escape(b['name'])+' '+str(w)+'"></a>' for w in [1920,960,390])+'</div></details></section>')
page='''<!doctype html><html lang="uk"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Konoha v18 — нові сцени</title><style>body{margin:0;background:#0b202b;color:#ead9b4;font:16px system-ui;line-height:1.6}main{max-width:1500px;margin:auto;padding:32px}h1,h2{line-height:1.2}h1{font-size:40px}h2{margin-top:0}p{max-width:1000px;color:#b8c8c5}a{color:#f4b969}section{margin:32px 0;padding:24px;border:1px solid #b9976544;background:#102b38;border-radius:8px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.pair.single{grid-template-columns:1fr}figure{margin:0}figcaption{color:#d4bc94;margin-bottom:8px}img{display:block;width:100%;height:auto}.screens{display:flex;align-items:start;gap:12px;margin-top:16px}.screens a{width:40%}.screens a:last-child{width:20%}summary{cursor:pointer;padding-top:16px}@media(max-width:650px){main{padding:16px}.pair{grid-template-columns:1fr}section{padding:12px}h1{font-size:30px}}</style><main><h1>Konoha · v18</h1><p>Нова поза Мінато, повністю нове тренування Расенсюрикена та рамен в Ічіраку. Три сцени зі скілом anime-tv-cel-art; попередні ресурси збережені. Значок вибору шпалер тепер показує два зображення.</p><p><a href="../../../prototype/">Відкрити інтерактивний лаунчер</a> · <a href="../REPORT.md">Звіт</a> · <a href="../generation-manifest.json">Точні промпти</a> · <a href="../references/sources.json">Джерела референсів</a></p>'''+''.join(parts)+'''<section><h2>Додаткові референси тренування</h2><a href="../references/training-board.jpg"><img src="../references/training-board.jpg" alt="Три фактичні кадри аніме: формування, стихія вітру, форма Расенсюрикена"></a><p>Формування і завершена техніка — різні моменти. Нова композиція показує завершення: оригінал утримує Расенсюрикен, два клони позаду. Четвертий персонаж із бойового кадру не переносився.</p></section><p>Перевірено у Chromium на 1920×1080, 960×540, 390×844. На вузькому екрані широкі сцени кадруються: повну композицію клонів і кунай видно на TV. Фізичний TV/пульт/WebView не перевірялися.</p></main></html>'''
(v/'visual-review.html').write_text(page,encoding='utf8')
sheet=Image.new('RGB',(1440,1220),'#102b38');d=ImageDraw.Draw(sheet)
for i,id in enumerate(['night','minato','ramen']):
 sheet.paste(ImageOps.contain(Image.open(v/f'{id}-960.png'),(480,280)),(i*480,24));d.text((i*480+12,6),id,fill='white');sheet.paste(Image.open(v/f'{id}-390.png'),(i*480+40,340))
sheet.save(v/'contact-sheet.jpg',quality=93)
(v/'source-hashes.json').write_text(json.dumps({p.relative_to(root).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in (root/'prototype').rglob('*') if p.is_file()},indent=2),encoding='utf8');print('v18 gallery and product hashes saved')
